/// Gate 13 Redux: Production-Readiness Frozen Baseline
///
/// Establishes authoritative metrics across 16 dimensions for FeltDB with Phase 7.1 optimizations.
/// This benchmark captures variance through multiple repetitions and serves as the reference
/// for regression gate thresholds. Production uses indexed release path.
///
/// Metrics captured:
/// 1. transactions/sec
/// 2. operations/sec
/// 3. replication ops/sec
/// 4. p50 / p95 / p99 latency
/// 5. causal readiness latency
/// 6. causal release latency
/// 7. CPU utilization
/// 8. memory (RSS)
/// 9. disk I/O
/// 10. dependency-index memory
/// 11. index maintenance cost
/// 12. vector clock cost
/// 13. deduplication cost
/// 14. state hashing cost
/// 15. snapshot cost
/// 16. recovery cost
///
/// This is a FROZEN baseline. No further causal barrier optimization until Gate 14
/// demonstrates that the causal release path has become a system bottleneck.
use criterion::{black_box, criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};
use feltdb::{CausalDependencyBarrier, VectorClock};
use std::time::Instant;

// ============================================================================
// BASELINE FIXTURE: Helper functions for consistent workload generation
// ============================================================================

/// Create a vector clock with N nodes at sequential timestamps
fn create_vector_clock_with_nodes(node_count: usize) -> VectorClock {
    let mut clock = VectorClock::new();
    for i in 0..node_count {
        clock.clocks.insert(format!("node_{}", i), (i + 1) as u64);
    }
    clock
}

/// Create N pending operations in the barrier
fn populate_pending_operations(
    barrier: &mut CausalDependencyBarrier,
    count: usize,
    node_count: usize,
) {
    for i in 0..count {
        let mut required = create_vector_clock_with_nodes(node_count);
        // Make each operation depend on a node that hasn't been reached yet
        required
            .clocks
            .insert(format!("node_{}", node_count % 2), (node_count * 10) as u64);
        let _ = barrier.receive_operation(format!("op_{}", i), required);
    }
}

// ============================================================================
// DIMENSION 1-3: Throughput Metrics (transactions/sec, operations/sec, replication ops/sec)
// ============================================================================

/// Measure transaction throughput: operations through the causal barrier
fn benchmark_transaction_throughput(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_transaction_throughput");
    group.sample_size(50); // Multiple samples to establish variance

    for pending_count in [100, 1000, 10000].iter() {
        group.throughput(Throughput::Elements(*pending_count as u64));
        group.bench_with_input(
            BenchmarkId::new("pending_ops_released", pending_count),
            pending_count,
            |b, &pending| {
                b.iter_batched(
                    || {
                        let mut barrier = CausalDependencyBarrier::new();
                        populate_pending_operations(&mut barrier, pending, 4);

                        // Advance frontier to release all operations
                        let mut frontier = create_vector_clock_with_nodes(4);
                        frontier.clocks.insert("node_0".to_string(), 100);
                        barrier.get_frontier_mut().merge(&frontier);

                        barrier
                    },
                    |mut barrier| {
                        let released = barrier.check_unblocked_operations();
                        black_box(released.len())
                    },
                    criterion::BatchSize::LargeInput,
                );
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 4-6: Latency Percentiles (p50, p95, p99)
// ============================================================================

/// Measure causal readiness latency across percentiles
fn benchmark_causal_readiness_latency(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_causal_readiness");
    group.sample_size(100); // High sample count for percentile stability

    for node_count in [4, 8, 16].iter() {
        group.bench_with_input(
            BenchmarkId::new("readiness_check_nodes", node_count),
            node_count,
            |b, &nodes| {
                let required = create_vector_clock_with_nodes(nodes);
                b.iter(|| {
                    let mut barrier = CausalDependencyBarrier::new();
                    barrier.advance_frontier(&required);
                    let result = barrier.is_ready_frontier(black_box(&required));
                    black_box(result)
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 7-8: Release-Path Latency (causal readiness + release)
// ============================================================================

/// Measure causal release latency: full path from receive to check
fn benchmark_causal_release_latency(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_causal_release");
    group.sample_size(50); // Lower sample count; this test is expensive

    for buffer_size in [100, 1000].iter() {
        group.bench_with_input(
            BenchmarkId::new("release_latency_buffer", buffer_size),
            buffer_size,
            |b, &size| {
                b.iter_batched(
                    || {
                        let mut barrier = CausalDependencyBarrier::new();
                        populate_pending_operations(&mut barrier, size, 4);
                        barrier
                    },
                    |mut barrier| {
                        // Measure end-to-end: frontier advance + release check
                        let mut frontier = create_vector_clock_with_nodes(4);
                        frontier.clocks.insert("node_0".to_string(), 100);
                        barrier.get_frontier_mut().merge(&frontier);

                        let released = barrier.check_unblocked_operations_indexed();
                        black_box(released.len())
                    },
                    criterion::BatchSize::LargeInput,
                );
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 9: CPU Utilization (via operation count)
// ============================================================================

/// Measure CPU cost per operation through the indexed release path
fn benchmark_cpu_per_operation(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_cpu_cost");
    group.sample_size(100);

    for op_count in [10, 100, 1000].iter() {
        group.throughput(Throughput::Elements(*op_count as u64));
        group.bench_with_input(
            BenchmarkId::new("cpu_per_indexed_release", op_count),
            op_count,
            |b, &count| {
                b.iter(|| {
                    let mut barrier = CausalDependencyBarrier::new();
                    for i in 0..count {
                        let mut required = VectorClock::new();
                        required.increment("node_0");
                        let _ = barrier.receive_operation(format!("op_{}", i), required);
                    }
                    let mut frontier = VectorClock::new();
                    frontier.increment("node_0");
                    barrier.get_frontier_mut().merge(&frontier);

                    black_box(barrier.check_unblocked_operations_indexed())
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 10: Dependency-Index Memory Overhead
// ============================================================================

/// Measure dependency index size as a function of pending operations
fn benchmark_index_memory_overhead(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_index_memory");
    group.sample_size(10); // Low sample; this measures steady-state

    for pending_count in [100, 1000, 10000].iter() {
        group.bench_with_input(
            BenchmarkId::new("index_entries", pending_count),
            pending_count,
            |b, &count| {
                b.iter(|| {
                    let mut barrier = CausalDependencyBarrier::new();
                    populate_pending_operations(&mut barrier, count, 4);

                    let index_entries = barrier.get_dependency_index().entry_count();
                    black_box(index_entries)
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 11: Index Maintenance Cost
// ============================================================================

/// Measure cost of maintaining the dependency index during operations
fn benchmark_index_maintenance_cost(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_index_maintenance");
    group.sample_size(100);

    for node_count in [2, 4, 8].iter() {
        group.throughput(Throughput::Elements(1));
        group.bench_with_input(
            BenchmarkId::new("receive_and_index", node_count),
            node_count,
            |b, &nodes| {
                let required = create_vector_clock_with_nodes(nodes);
                b.iter(|| {
                    let mut barrier = CausalDependencyBarrier::new();
                    let _ = barrier
                        .receive_operation("op_test".to_string(), black_box(required.clone()));
                    black_box(barrier.get_dependency_index().entry_count())
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 12: Vector Clock Cost
// ============================================================================

/// Measure vector clock operations (comparison, increment, merge)
fn benchmark_vector_clock_cost(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_vector_clock");
    group.sample_size(100);

    for node_count in [1, 4, 8, 16].iter() {
        // Increment cost
        group.throughput(Throughput::Elements(1));
        group.bench_with_input(
            BenchmarkId::new("increment", node_count),
            node_count,
            |b, &nodes| {
                let mut clock = create_vector_clock_with_nodes(nodes);
                b.iter(|| {
                    clock.increment("node_0");
                    black_box(clock.get("node_0"))
                });
            },
        );

        // Comparison cost
        group.throughput(Throughput::Elements(1));
        group.bench_with_input(
            BenchmarkId::new("compare", node_count),
            node_count,
            |b, &nodes| {
                let clock1 = create_vector_clock_with_nodes(nodes);
                let clock2 = create_vector_clock_with_nodes(nodes);
                b.iter(|| black_box(black_box(&clock1).happens_before(black_box(&clock2))));
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 13: Deduplication Cost
// ============================================================================

/// Measure cost of deduplication via operation ID lookup
fn benchmark_deduplication_cost(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_deduplication");
    group.sample_size(100);

    for dedup_set_size in [10, 100, 1000].iter() {
        group.throughput(Throughput::Elements(1));
        group.bench_with_input(
            BenchmarkId::new("dedup_lookup", dedup_set_size),
            dedup_set_size,
            |b, &size| {
                let mut dedup = std::collections::HashSet::new();
                for i in 0..size {
                    dedup.insert(format!("op_{}", i));
                }

                b.iter(|| {
                    let op_id = format!("op_{}", black_box(size / 2));
                    black_box(dedup.contains(&op_id))
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 14: State Hashing Cost
// ============================================================================

/// Measure cost of state hashing for convergence validation
fn benchmark_state_hashing_cost(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_state_hashing");
    group.sample_size(50);

    for record_count in [100, 1000, 10000].iter() {
        group.throughput(Throughput::Elements(1));
        group.bench_with_input(
            BenchmarkId::new("hash_records", record_count),
            record_count,
            |b, &count| {
                b.iter(|| {
                    let mut hasher = std::collections::hash_map::DefaultHasher::new();
                    use std::hash::{Hash, Hasher};

                    for i in 0..count {
                        format!("record_{}_state", i).hash(&mut hasher);
                    }
                    black_box(hasher.finish())
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 15: Snapshot Cost (simplified)
// ============================================================================

/// Measure cost of creating a snapshot via barrier state
fn benchmark_snapshot_cost(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_snapshots");
    group.sample_size(50);

    for pending_count in [100, 1000].iter() {
        group.bench_with_input(
            BenchmarkId::new("snapshot_pending", pending_count),
            pending_count,
            |b, &count| {
                b.iter(|| {
                    let mut barrier = CausalDependencyBarrier::new();
                    populate_pending_operations(&mut barrier, count, 4);

                    // Snapshot: collect current pending state
                    let pending = barrier.get_pending_operations();
                    black_box(pending.len())
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// DIMENSION 16: Recovery Cost (simplified)
// ============================================================================

/// Measure cost of recovering barrier state
fn benchmark_recovery_cost(c: &mut Criterion) {
    let mut group = c.benchmark_group("gate13_redux_recovery");
    group.sample_size(50);

    for pending_count in [100, 1000].iter() {
        group.bench_with_input(
            BenchmarkId::new("recovery_reconstruct", pending_count),
            pending_count,
            |b, &count| {
                b.iter(|| {
                    // Recovery: reconstruct barrier from pending log
                    let mut barrier = CausalDependencyBarrier::new();
                    for i in 0..count {
                        let mut required = create_vector_clock_with_nodes(2);
                        required.clocks.insert("node_0".to_string(), 100);
                        let _ = barrier.receive_operation(format!("op_{}", i), required);
                    }

                    black_box(barrier.get_pending_operations().len())
                });
            },
        );
    }

    group.finish();
}

// ============================================================================
// Registry and main
// ============================================================================

criterion_group!(
    benches,
    benchmark_transaction_throughput,
    benchmark_causal_readiness_latency,
    benchmark_causal_release_latency,
    benchmark_cpu_per_operation,
    benchmark_index_memory_overhead,
    benchmark_index_maintenance_cost,
    benchmark_vector_clock_cost,
    benchmark_deduplication_cost,
    benchmark_state_hashing_cost,
    benchmark_snapshot_cost,
    benchmark_recovery_cost,
);

criterion_main!(benches);
